function onWindowResize() {
  var newWidth = window.innerWidth;
  var newHeight = window.innerHeight;
  renderer.setSize(newWidth, newHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  var aspectRatio = newWidth / newHeight;
  global.aspectRatio = aspectRatio;
  global.scale = [1, 1];
  if (imageAspect > aspectRatio) {
    global.scale = [imageAspect / aspectRatio, 1];
  } else {
    global.aspectRatio = imageAspect;
    global.scale = [1, aspectRatio / imageAspect];
  }
  camera.left = window.innerWidth / -60,
  // left
  camera.right = window.innerWidth / 60,
  // right
  camera.top = window.innerHeight / 60,
  // top
  camera.bottom = window.innerHeight / -60,
  // bottom

  camera.updateProjectionMatrix();
  app.resize(global.scale);
  resizeVariables();
  _ScrollTrigger.ScrollTrigger.refresh();
}
window.addEventListener('resize', onWindowResize, false);
